import{_ as t,o,c as n,ak as i}from"./chunks/framework.sV-XtlWr.js";const w=JSON.parse('{"title":"Editor connection","description":"Connect the Piwi extension for VS Code or the JetBrains plugin to your instance: the connection the reporter already uses, or a browser sign-in that creates an API key for the editor, saved for that instance only.","frontmatter":{"title":"Editor connection","description":"Connect the Piwi extension for VS Code or the JetBrains plugin to your instance: the connection the reporter already uses, or a browser sign-in that creates an API key for the editor, saved for that instance only.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editor-connection.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editor-connection.html"}],["meta",{"property":"og:title","content":"Editor connection | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Connect the Piwi extension for VS Code or the JetBrains plugin to your instance: the connection the reporter already uses, or a browser sign-in that creates an API key for the editor, saved for that instance only."}]]},"headers":[],"relativePath":"features/editor-connection.md","filePath":"features/editor-connection.md","lastUpdated":1790686844000}'),r={name:"features/editor-connection.md"};function s(a,e,c,h,d,l){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="editor-connection" tabindex="-1">Editor connection <a class="header-anchor" href="#editor-connection" aria-label="Permalink to &quot;Editor connection&quot;">​</a></h1><p>The <a href="./editors.html">editor extensions</a> read everything from your Piwi instance. They find it in this order, and the first that names an instance wins:</p><ol><li><code>PIWI_DASHBOARD_URL</code>, <code>PIWI_API_KEY</code> and <code>PIWI_PROJECT_NAME</code> in the environment the editor was started with;</li><li>the same variables in the <code>.env</code> next to the Playwright config, then at the repository root (a URL there takes only its own key);</li><li>the <a href="/features/desktop.html">desktop app</a>, when it runs;</li><li>the editor&#39;s own settings, which <strong>Piwi: Connect</strong> fills in.</li></ol><p>A project set up for the reporter needs nothing more. An editor started from the Dock or the Start menu may not see the variables your shell exports: the <code>.env</code> or Connect work either way.</p><h2 id="connect" tabindex="-1">Connect <a class="header-anchor" href="#connect" aria-label="Permalink to &quot;Connect&quot;">​</a></h2><p>Run <strong>Piwi: Connect</strong> from the command palette, or click <strong>Piwi: connect</strong> in the status bar. In a JetBrains IDE it is the <strong>Connect…</strong> button of <strong>Settings → Tools → Piwi</strong>, in the <strong>Piwi</strong> tool window&#39;s toolbar, and under <strong>Tools → Piwi</strong>.</p><ol><li>Give the instance&#39;s address, such as <code>https://piwi.example.com</code>.</li><li>When the instance has a login, choose <strong>Sign in with the browser</strong>. The instance&#39;s page opens with a code: check that the editor shows the same code, then click <strong>Allow</strong>. The editor receives an <a href="/operate/api-keys.html">API key</a> created for you and named after it, such as &quot;Piwi in WebStorm on macOS&quot;, which you can revoke with your other keys. Or paste a key you created yourself. An instance without a login needs no key.</li><li>Pick the project.</li></ol><p>When the environment, a <code>.env</code> or the desktop app names another instance, Connect saves your choice and says which source comes first.</p><h2 id="what-is-saved-where" tabindex="-1">What is saved where <a class="header-anchor" href="#what-is-saved-where" aria-label="Permalink to &quot;What is saved where&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>VS Code</th><th>JetBrains IDEs</th></tr></thead><tbody><tr><td>Address and project</td><td><code>piwi.serverUrl</code> and <code>piwi.project</code> in the workspace settings</td><td><code>.idea/piwi.xml</code></td></tr><tr><td>API key</td><td>The editor&#39;s secret storage</td><td>The IDE&#39;s password safe</td></tr></tbody></table><p>The address and the project can be shared with the team. The key never goes to a file, and is saved for its instance only: a repository whose settings name another instance never receives it. <strong>Piwi: Disconnect</strong> (the <strong>Disconnect</strong> button in a JetBrains IDE) forgets the address, the project and that instance&#39;s key.</p><h2 id="which-connection-is-in-use" tabindex="-1">Which connection is in use <a class="header-anchor" href="#which-connection-is-in-use" aria-label="Permalink to &quot;Which connection is in use&quot;">​</a></h2><p>The status bar&#39;s tooltip names the instance and where it came from. In a JetBrains IDE, <strong>Settings → Tools → Piwi</strong> and the <strong>Piwi</strong> tool window say the same, or why the editor is not connected. The plugin starts its service when you open a file of a project that holds a Playwright config; until then, both say so.</p><p><strong>Piwi: Open settings</strong> in VS Code opens the extension&#39;s settings.</p>',14)])])}const g=t(r,[["render",s]]);export{w as __pageData,g as default};
